CREATE DATABASE IF NOT EXISTS terqivo CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE terqivo;

CREATE TABLE IF NOT EXISTS admin_users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(160) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role VARCHAR(30) NOT NULL DEFAULT 'admin',is_active TINYINT(1) NOT NULL DEFAULT 1,last_login_at TIMESTAMP NULL,remember_token VARCHAR(100) NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL);
CREATE TABLE IF NOT EXISTS products (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,slug VARCHAR(180) NOT NULL UNIQUE,short_description TEXT NOT NULL,description LONGTEXT NULL,logo VARCHAR(255) NULL,featured_image VARCHAR(255) NULL,website_url VARCHAR(500) NULL,status VARCHAR(30) NOT NULL DEFAULT 'coming_soon',featured TINYINT(1) NOT NULL DEFAULT 0,sort_order INT UNSIGNED NOT NULL DEFAULT 0,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,INDEX(status));
CREATE TABLE IF NOT EXISTS courses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(160) NOT NULL,slug VARCHAR(180) NOT NULL UNIQUE,category VARCHAR(100) NULL,short_description TEXT NOT NULL,description LONGTEXT NULL,price DECIMAL(10,2) NULL,currency VARCHAR(8) NOT NULL DEFAULT 'PKR',duration VARCHAR(80) NULL,level VARCHAR(40) NOT NULL DEFAULT 'Beginner',format VARCHAR(40) NOT NULL DEFAULT 'Online',enrollment_status VARCHAR(40) NOT NULL DEFAULT 'Coming Soon',student_limit INT UNSIGNED NULL,featured_image VARCHAR(255) NULL,certificate_available TINYINT(1) NOT NULL DEFAULT 1,featured TINYINT(1) NOT NULL DEFAULT 0,published TINYINT(1) NOT NULL DEFAULT 1,sort_order INT UNSIGNED NOT NULL DEFAULT 0,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL);
CREATE TABLE IF NOT EXISTS services (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,slug VARCHAR(180) NOT NULL UNIQUE,short_description TEXT NOT NULL,description LONGTEXT NULL,icon VARCHAR(100) NULL,featured_image VARCHAR(255) NULL,published TINYINT(1) NOT NULL DEFAULT 1,featured TINYINT(1) NOT NULL DEFAULT 0,sort_order INT UNSIGNED NOT NULL DEFAULT 0,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL);
CREATE TABLE IF NOT EXISTS posts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(160) NOT NULL,slug VARCHAR(180) NOT NULL UNIQUE,category VARCHAR(100) NULL,author VARCHAR(100) NOT NULL DEFAULT 'Terqivo Editorial',excerpt TEXT NULL,content LONGTEXT NULL,featured_image VARCHAR(255) NULL,status VARCHAR(30) NOT NULL DEFAULT 'draft',featured TINYINT(1) NOT NULL DEFAULT 0,published_at TIMESTAMP NULL,meta_title VARCHAR(180) NULL,meta_description TEXT NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,INDEX(status));
CREATE TABLE IF NOT EXISTS career_jobs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(160) NOT NULL,slug VARCHAR(180) NOT NULL UNIQUE,department VARCHAR(100) NOT NULL,location VARCHAR(100) NULL,employment_type VARCHAR(80) NULL,experience_level VARCHAR(80) NULL,short_description TEXT NULL,description LONGTEXT NOT NULL,requirements LONGTEXT NULL,status VARCHAR(30) NOT NULL DEFAULT 'draft',deadline DATE NULL,featured TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,INDEX(status));
CREATE TABLE IF NOT EXISTS contact_messages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(160) NOT NULL,phone VARCHAR(40) NULL,company VARCHAR(120) NULL,subject VARCHAR(180) NOT NULL,message LONGTEXT NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'new',created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,INDEX(status));
CREATE TABLE IF NOT EXISTS certificates (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,certificate_number VARCHAR(80) NOT NULL UNIQUE,student_name VARCHAR(160) NOT NULL,student_email VARCHAR(160) NULL,course_id BIGINT UNSIGNED NULL,course VARCHAR(160) NOT NULL,issue_date DATE NOT NULL,certificate_image VARCHAR(255) NULL,verification_code VARCHAR(100) NOT NULL UNIQUE,status VARCHAR(30) NOT NULL DEFAULT 'active',created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL);
CREATE TABLE IF NOT EXISTS site_settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,`key` VARCHAR(160) NOT NULL UNIQUE,`value` TEXT NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL);
CREATE TABLE IF NOT EXISTS media (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255) NOT NULL,path VARCHAR(500) NOT NULL,mime_type VARCHAR(120) NOT NULL,size BIGINT UNSIGNED NOT NULL,disk VARCHAR(30) NOT NULL DEFAULT 'public',created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL);
